import{_ as e,C as t,o as a,c as i,j as o,a as r,E as s,a6 as n}from"./chunks/framework.CnPv4DE1.js";const m=JSON.parse('{"title":"专注的艺术：作者丹·科伊(Dan Koe)官方图书摘要","description":"","frontmatter":{"title":"专注的艺术：作者丹·科伊(Dan Koe)官方图书摘要","originalTitle":"The Art Of Focus: Official Book Summary By The Author Dan Koe","date":"2023-10-28","originalUrl":"https://thedankoe.com/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe/","minutes":41,"sourceHash":"1d8f32b63d57f237b5d735427a7f9e916eef86413386000f4c47e5f7a01255d2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe/"}]]},"headers":[],"relativePath":"letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe.md","filePath":"letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe.md"}'),h={name:"letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe.md"};function u(c,p,b,f,k,d){const l=t("ArticleMeta");return a(),i("div",null,[p[0]||(p[0]=o("h1",{id:"专注的艺术-作者丹·科伊-dan-koe-官方图书摘要",tabindex:"-1"},[r("专注的艺术：作者丹·科伊(Dan Koe)官方图书摘要 "),o("a",{class:"header-anchor",href:"#专注的艺术-作者丹·科伊-dan-koe-官方图书摘要","aria-label":'Permalink to "专注的艺术：作者丹·科伊(Dan Koe)官方图书摘要"'},"​")],-1)),s(l),p[1]||(p[1]=n('<p><a href="https://www.youtube.com/embed/iX5CgAwxAtc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>《专注的艺术》是一套实用哲学，帮助你找到意义、重塑自我，并创造你理想的未来。</p><p>我是作者丹·科伊(Dan Koe)，我会在别人抢先之前，写出这本书自己的摘要版本。这样我才能为各章节提供正确的背景。</p><p>我会尽量涵盖高层次的原则和建议，但我写这本书是有原因的。有些内容几乎无法省略。如果你对完整的教学内容感兴趣，我建议你<a href="http://theartoffocusbook.com/" target="_blank" rel="noreferrer">在这里获取这本书</a>。</p><p>如果你愿意，也可以在这里下载<a href="https://drive.google.com/drive/folders/1aehBdrQnXDTyEjzbDJfOWu9IC7f5SrWR?usp=sharing" target="_blank" rel="noreferrer">本摘要的PDF或ePub版本</a>。</p><p>我建议使用<a href="https://read.readwise.io/" target="_blank" rel="noreferrer">Readwise Reader</a>以获得更好的移动端阅读体验。</p><p>在桌面端操作最简单。注册一个Reader账号，下载上面的ePub文件，然后拖入Reader中即可。你也可以把它发送到你的Kindle邮箱，或用手机上的默认阅读器打开。</p><p><strong>阅读时间：</strong> 30-40分钟</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">引言</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">原则</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">三大支柱</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">宇宙</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">自我</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">游戏</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">透镜</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">公式</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">转变</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">新富人</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">技能堆栈</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">项目</a></li><li><a href="/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">载体</a></li></ol><h2 id="一-–-引言" tabindex="-1">一 – 引言 <a class="header-anchor" href="#一-–-引言" aria-label="Permalink to &quot;一 – 引言&quot;">​</a></h2><p>本书开篇描绘了现代世界的现状。</p><blockquote><p>醒来。按四次贪睡键。盯着手机看。爬下床。煮咖啡。堵在路上。八小时毫无成就感的工作。再堵一次车……和你“重要的另一半”争吵。遛宠物。看电视。昏睡过去。重复。</p></blockquote><p>人类被训练去遵循社会设定的默认人生路径。那99%的人做别人告诉他们的事，从不质疑，把自己知道的东西照搬传下去，最终导致一群无法独立思考的人。</p><p>这导致了一种迟钝、机械、毫无思考的生活。</p><p>在我小时候，我就观察到：如果每个人都做同样的事，他们就会得到同样的结果，而不难看出，大多数人对这些结果并不满意。</p><p>很少有人设定自己的目标，能坚持下去的人更少。然而这恰恰是唯一能进化的方式。目标意味着一个问题，正是这个问题让你发展自己的技能与心智。也正是它让你形成更复杂的身份，从而能在生活中找到意义与进步。</p><p>这种“默认路径”在我们的时代格外明显。这正是你必须克服的主要问题。</p><p>信息、机会与便利如今泛滥成灾。我们会把其中大多数——除了那些你用批判性思维筛选出来的——统称为“干扰”。干扰会让你离真正的自己、以及你想成为的样子越来越远。</p><p><strong>平庸生活的解药，就是专注。</strong></p><blockquote><p>人类的自觉注意力每秒能处理10到50比特信息。我们选择处理哪些信息（内容是什么）、如何处理（怎么解读）、以及为什么处理（起初为何投入注意力），这三者将决定我们的生活质量。也就是说，我们的注意力所停留之处、我们如何解读这些信息、以及我们最初为何将注意力投向它，都至关重要。</p></blockquote><p>我们可以把你一生中通过专注所处理的大约1250亿比特信息，视为你的潜能。</p><p>由于其中一大部分被用在了梳洗、跑腿和其他基本事务上，我们必须极其重视自己把注意力投向何处，因为这将决定我们人生的结果。</p><p>在整本书中，我只希望你做到：</p><ul><li><strong>以彻底开放的心态去阅读。</strong> 不要立刻贴标签或做判断，而是通过直接的体验去理解我所说的内容。这可能需要几天、几年，甚至几十年。</li><li><strong>质疑、挑战并在这些想法之上构建。</strong> 这本书中的想法会塑造你人生的结果，正如你遇到的任何其他想法一样。我希望你能运用它们、检验它们、迭代它们，并让它们变得更好，从而为人类做出贡献。</li><li><strong>不要把我说的话当作法则。</strong> 我只是无数视角中的一个。我所说的一切都不是绝对真理。它在某些情境下对我的生活有用，也可能对你的生活有用，但也可能完全没有共鸣。</li></ul><p>话说到这里，让我们深入这本书的核心内容。</p><h2 id="二-–-原则" tabindex="-1">二 – 原则 <a class="header-anchor" href="#二-–-原则" aria-label="Permalink to &quot;二 – 原则&quot;">​</a></h2><p>原则是永恒的，战术却随时代而变。</p><p>这并不意味着你应该忽视战术，但要知道，无论在生活的哪个领域，战术所带来的效果都是暂时的。</p><p>《专注的艺术》是围绕27条原则写成的。我会在这里以快速列举的方式呈现它们。</p><ol><li><p>宇宙的至高法则是<strong>熵增</strong>。没有什么是永恒的——从情绪、想法，到你的健康，再到教育系统赖以维系你未来保障的那些体系。</p></li><li><p><strong>系统思维</strong>——即理解现实中任何角落的目标、过程与问题——是你在局势中为自己谋取优势的方式。</p></li><li><p><strong>心理熵</strong>——即心智中的混乱——意味着我们必须通过自我设定的目标、实现这些目标的路径，以及此刻要专注解决的问题，来在生活中创造并维持秩序，这样我们才不会被干扰所吞噬。</p></li><li><p>我们注意力所聚焦信息的结构——也就是<strong>意识中的内容</strong>——决定了我们生活的质量。但信息本身就是“正在形成之物”，它始终在变化，无法永恒。你所专注的东西，必须每天、每月、每年都随之调整改变。</p></li><li><p><strong>放大视角</strong>去看清一个局面的全貌，能让你看清负面情况的本质……其实没那么严重。</p></li><li><p><strong>自我实验</strong>是彻底解决你自身问题、在生活中做出全新发现、获得真正经验的唯一方法。</p></li><li><p>你的心智是一台信息处理机器。为了生存，我们会模仿周围的环境。<strong>智慧的模仿</strong>能让你利用“融入群体”的好处，同时不至于沦为社会体制的无脑奴仆。</p></li><li><p>封闭的心态会让你与那些本可能被发现的发现、洞见和真理彻底隔绝。<strong>彻底的开放心态</strong>能让你作为个体不断扩展，并收集成功所必需的视角。</p></li><li><p><strong>观察与提问</strong>是你学会以智慧和从容应对困境的方式。</p></li><li><p><strong>判断与明辨</strong>之间存在区别。判断会导致心态封闭，而明辨则能让你从他人的经验中汲取养分，从而为自身的发展做出明智的决定。</p></li><li><p>大多数人痛苦的根源，是<strong>人们的期望与情境实际情况之间的落差</strong>。当下这一刻本不该是别的样子，它就该是它现在这个样子。</p></li><li><p>当你练习<strong>彻底的接纳</strong>时，你才开始看清事物的本质。没有任何一种“想法”能改变现实的情况。</p></li><li><p><strong>一个人可以知道很多，却理解甚少</strong>。知识是向上构建的，而理解是向内发现的。</p></li><li><p>做出全新发现的唯一方法，就是去探索未知。<strong>现实探索</strong>必须成为一种日常实践。你必须刺破那条你被训练去过的默认人生轨道。</p></li><li><p>这个世界需要更多<strong>整体性的综合者</strong>——那些去探索现实、在多个领域之间连接线索的人，而不是困在某一个小圈子里，把自己整个身份都建立在那上面。</p></li><li><p>现代世界重视<strong>生产力却忽视了创造力</strong>。这导致人们变成机械化、高效但不再像“人”的机器。你可以建立你的心智所喜爱的高效系统，但也别犹豫超越它们，去发现下一个必须解决的问题。</p></li><li><p>心智通过<strong>讲故事</strong>来理解这个世界。生活以章节和阶段的形式展开——那是问题、冒险的召唤、好奇心、未知的探索、挣扎、洞见、转变、解决方案与高潮的层层展开。顺应这一切流动。</p></li><li><p><strong>没有失败，就没有成功</strong>。失败是一个参照点，它揭示出一个问题，从而让你从中生成一个目标，去发现一个教训。</p></li><li><p><strong>迭代与坚持</strong>胜过安于现状与一成不变的坚持。</p></li><li><p><strong>现实并非黑白分明</strong>，但极端的观点却最容易吸引注意。真正的魔力，只存在于那片灰色地带，而只有不断质疑一切，才能找到它。</p></li><li><p>我们的视角决定了我们对情境是做出正面还是负面的解读。真理的追寻者必须去搜寻真理的碎片，从而<strong>培养出更全面的视角</strong>，让更多正向的解读成为可能。</p></li><li><p><strong>你不是要摆脱自我（ego），而是要发展它</strong>，直到它与现实融为一体。</p></li><li><p>你在生活中遇到的每一个问题，都要求你的<strong>心智层级</strong>提升、视角变得更开阔、或自我变得更复杂。</p></li><li><p><strong>人类靠精神层面生存</strong>。我们靠的是那个被称为“身份认同”的想法，以及一切能让这个身份维持其形态的东西而存活。</p></li><li><p><strong>精通</strong>能让你在一个看不见表面之下的悲惨世界里脱颖而出。</p></li><li><p><strong>战术性压力</strong>是一种策略——让自己主动投身未知，去看看自己究竟能做到什么程度。它会强制你去学习、去获取技能、去拓展视角。</p></li><li><p>如果你<em>需要</em>从别人那里得到某种东西，你几乎不可能做到真实地行事。<strong>自私</strong>对于那些尚未把自己发展到独立自主境地的人来说，必须是首要之事。</p></li></ol><h2 id="三-–-三大支柱" tabindex="-1">三 – 三大支柱 <a class="header-anchor" href="#三-–-三大支柱" aria-label="Permalink to &quot;三 – 三大支柱&quot;">​</a></h2><p>根据我的探索、经验与反思，美好生活有三大支柱：专注、精力和体验。</p><blockquote><p>能够将注意力聚焦在一个有意义的目标上，把它放在脑海深处作为分心的驱除剂，凭借以往的经验清楚地知道如何实现它，并在面对每一个选择时重新聚焦——这是一种超能力。</p></blockquote><h3 id="_1-–-专注" tabindex="-1">1 – 专注 <a class="header-anchor" href="#_1-–-专注" aria-label="Permalink to &quot;1 – 专注&quot;">​</a></h3><p>专注是一种可以训练的肌肉。就像你可以通过体能训练来锻炼身体一样，你也可以通过心智训练来锻炼大脑。</p><p>专注有一个我们称之为视角（perspective）或世界观的框架。这个框架是由你一生中处理的信息塑造而成的。你的视角限制了你在任何情境下能够感知和解读的内容。</p><p>视角是由你计划实现的目标、你所知道的实现这些目标的路径，以及为实现这些目标而必须识别出的问题所构建的。<strong>注意：</strong>如果你不知道自己在追求什么目标，那你追求的就是社会分配给你的目标。</p><p>你的专注将局限于你的视角所允许的现实层面。除非你设立能将你推向未知领域的目标，否则一个你视为生活常态的问题，永远不会显现为一个真正的问题。正因如此，你将没有任何有意义的东西可以学习、发现或采取行动。这就是你训练专注力的方式：通过设立并追求基于兴趣的目标，让你的大脑意识到新的信息，从而推动你自身的进化。</p><p>这凸显了彻底开放心态的重要性。如果你长期处于封闭心态、压力和狭隘专注的状态中，一个能改变你人生的机会可能会从你身边悄然溜走。而你会怪罪任何人、任何事，唯独不怪自己，来为自己的无能开脱。</p><p>随着时间推移，你新训练出的大脑将获得从噪音中过滤出信号的能力，你的专注也会自然而然地偏向那些能为你的生活带来繁荣的信息。</p><h3 id="_2-–-能量" tabindex="-1">2 – 能量 <a class="header-anchor" href="#_2-–-能量" aria-label="Permalink to &quot;2 – 能量&quot;">​</a></h3><blockquote><p>具体的目标需要具体数量的心智能量才能实现。</p></blockquote><p>当你被锁死在默认路径上时，你正把心智能量花在社会分配给你的目标上。这使得你很难把资源投入到自己真正想要实现的目标中。</p><p>熵，或者说自然的税收，是衡量一个系统中无序程度的指标，也是推动进化的驱动力。它表明，除非有人努力逆转熵增，否则万物都会随时间瓦解。维持一个系统的秩序需要能量。</p><p>一个系统有其目的、实现这一目的的路径，以及沿途需要投入能量去解决的问题。社会已经花了数年时间来构建争夺大众注意力的系统。如果你不想过平庸的一生，就必须花时间在你生活的各个领域中去创建并维护属于自己的系统。</p><p>你必须在健康、财富、人际关系和幸福这些领域中建立一个目标层级，并经常——如果不是每天——向它们投入心智能量。如果你不这样做，你就只会继续沿着默认路径走下去，最终变得和其他人一样。而那并不美好。</p><h3 id="_3-–-经验" tabindex="-1">3 – 经验 <a class="header-anchor" href="#_3-–-经验" aria-label="Permalink to &quot;3 – 经验&quot;">​</a></h3><blockquote><p>经验、生活和科学的本质就是试错。你不能把任何想法、观点或建议未经直接经验的过滤就当作法则来接受。即便这是我自己的建议，也是如此。</p></blockquote><p>经验的获得，是通过识别你生活中的问题、解决它们，并通过不断进化你大脑运作所依赖的系统，让你的处理流程变得更高效。</p><p>随着经验的积累，专注与能量之间的反馈回路会不断收紧。你在人生中的成果会呈复利式增长，因为你从所解读的信息中筛选出的东西，更有利于采取有意义的行动。</p><h2 id="iv-–-宇宙" tabindex="-1">IV – 宇宙 <a class="header-anchor" href="#iv-–-宇宙" aria-label="Permalink to &quot;IV – 宇宙&quot;">​</a></h2><blockquote><p>挣扎是一种宇宙法则。认为它不该成为你生活的一部分，这种想法是幼稚的。但我们恰恰就是这样想的。我们期待生活按某种特定方式展开，而生活本不该是除了它本来的样子之外的任何东西。</p></blockquote><p>宇宙（The Universe）就是现实的本体。</p><p>我选择用首字母大写的“宇宙（Universe）”这个词，而不是像“上帝”“梵（Brahman）”或“特奥特尔（Teotl）”这样的文化标签，原因有二：一是它们都指向同一个东西；二是人们对自己所认同的那个标签会有过度的情感执着。人们在概念层面上争论不休，却在体验层面上其实是一致的。</p><p>无论你信仰什么，为了让这一切说得通：宇宙就是一切。这个词是一个指向某种体验的概念。你曾体验过它，只是你可能不会用这个词来标记它，因为你的条件反射式思维已经把你逼进了一个狭隘的视角，让你无法整合那些你以为自己不认同的信仰体系中的真理——其实那不是不认同，而是误解。这话出自一个曾经的无神论者、重度怀疑主义者之口。走出你的脑袋。再多的语言也无法证明是什么让语言得以存在。</p><p>宇宙被划分为无限的、被称为“想法”的创造性部分。万事万物，或者说每一个想法，都是相互连接、层层叠加的，以此让你能够理解这个世界。</p><p>你之所以没有目标感，是因为你与那些能让你看清目标的想法脱节了。你还没有把现实探索到足以理解——或者创造——自己在这个世界中的位置的程度。</p><p>这些想法是无常的、不断流动的。这“宇宙（Uni-verse）”，或者说“一首歌”，可以被看作是一段在你眼前展开的和声。其中有高潮、有低谷、有问题、有解决方案，有上升的行动、下降的行动、顶点，也有结局。这些模式反映在生活的各个层面——尤其是构成大多数情境结构的故事和游戏，只是很少有人退后一步去观察这种结构。</p><p>从实际层面来说，当人们无法看清完整的故事或游戏全局时，他们就会感到痛苦。他们用自己的专注力把某一个情境孤立出来，像一张静止的图像一样固定在脑海中。而现实正在向前推进，你却困在过去。</p><blockquote><p>当我们运用大脑的创造力从更高处俯瞰生活时，我们就能发现、收集并利用那些深刻的洞见，为我们脚下的世界带来平静与进步。</p></blockquote><p>你觉得生活毫无意义，是因为你没有立足于当下这一刻。这与有组织的宗教或某种信仰体系无关。这关乎能否触及现有的最高视角，从而变得比以往任何时候都更具创造力。</p><p>如果创造力是让自己变得不可替代的关键，而你的创造力又取决于你心智的开放程度或扩展程度，那么把宇宙理解为一种自然法则，将让你领先99%的人。上如是，下亦然。</p><h2 id="v-–-自我" tabindex="-1">V – 自我 <a class="header-anchor" href="#v-–-自我" aria-label="Permalink to &quot;V – 自我&quot;">​</a></h2><blockquote><p>你正被吸引向自己最高的版本，而你内核的深处能感知到这一点。这种向外的进化召唤，要求你向内雕琢，穿透那些在你的条件反射式思维中层层堆叠起来的心智构造。你的内在状态必须与不断变化的外在状态融为一体。</p></blockquote><p>人类是模式识别与学习的机器。从我们出生起，我们就像海绵一样吸收各种想法，并把一群群的想法，也就是意识形态，当作法则接受下来。这使我们的心智变得狭隘，限制了我们对“重要”的理解。</p><p>社会很早就影响了我们，因为大多数人都是浑然不觉的，而那些塑造我们心智的朋友、父母和老师，他们自己的心智也曾被他们的朋友、父母和老师塑造过。很少有人拥有一个真正经由批判性思维、自我设定的目标以及开拓自己道路而有意识地打造出来的“自我”。</p><p>在年幼时，我们就已经超越了对生理生存的需求。我们不必再为此过多担忧。而正是在这里，一种更危险的东西开始起作用：概念层面的生存，也就是维系“你是谁”这个想法的生存。</p><p>这在宗教、政治，以及像咖啡爱好者这样的小众社群中随处可见。如果你被灌输了一套宗教信仰体系，当有人挑战这些信念时，你会感到受到威胁。就像一只被蛇缠住的老鼠，你会奋力反击，试图通过告诉对方“你错了”来复制脑中的那些想法。</p><ul><li>共和党人和民主党人正处于一场关于他们所执着的对立想法的战争之中。当有人挑战他们的信念时，他们会感到人身受到了威胁。</li><li>如果你最喜欢的运动队输了，或者有人说他们是支烂队，你会有什么感觉？你的生存真的受到威胁了吗？还是你没看清，你正在为一个虚构的概念表现得多么荒唐？</li><li>当你体重增加时，你担忧的是身体上多出来的那些重量，还是担忧“我是一个健康的人”这个身份概念即将死去？</li></ul><p>在每一个情境中，你都在通过言语和行动生存并繁衍着你的身份认同。如果你不是自己创造出来的，那你就是在不知不觉中助长了浑然无知、邪恶与毁灭的蔓延。而你可能根本不在乎。</p><p>如果我们想要创造一个少劳多得、享受生活、并让自己的想法在宇宙中激起涟漪从而缔造天堂的身份认同，这个过程将会是痛苦的。</p><p>把你的“自我”想象成一个智识结构——一座房子，但不是一个家。当你要翻修一座房子时，你不会把地基拆掉然后看着它倒塌。你会随着意识到那些破坏房子美观和功能的问题，做出小而有策略的改动。</p><p>要改变你是谁，你必须解决那些与你自己设立的目标相一致的问题，而不是别人分配给你的目标。</p><p>这就是带着目的生活的方式。</p><p>从表层问题开始着手，这样你才能停止活在那种狭隘、充满压力的状态中。先解决健康问题，解决金钱问题，解决人际关系问题，然后再深入探究你那不断进化的人生目的。</p><p>大多数人“找不到自己的目的”，是因为他们看不见那个目的其实就摆在他们眼前。你必须先解决那些迫切的问题，正是这些问题阻碍了你的心智扩展到浅层生活之外。</p><p>你并没有一个唯一的目的。</p><p>随着时间、努力以及自我的不断进化，你会从较小的目的走向更宏大的目的。</p><h2 id="vi-–-游戏" tabindex="-1">VI – 游戏 <a class="header-anchor" href="#vi-–-游戏" aria-label="Permalink to &quot;VI – 游戏&quot;">​</a></h2><p>生活就像一场电子游戏。</p><p>我喜欢把生活和大型多人在线角色扮演游戏《魔兽世界（World Of Warcraft）》联系起来，我十几岁时在这个游戏上花的时间实在有点太多了。</p><p>在游戏中，你会遇到一系列选择和新手教程。</p><ul><li>你选择你的种族</li><li>你选择你的职业</li><li>你选择你的外观</li><li>你被投放到相对应的初始区域</li><li>你被教授游戏的基础知识、规则和机制</li><li>你练习，升几级，然后作为主角开始你的旅程</li><li>你解锁技能、特质、职业选项、专属掉落的地下城，以及加入公会和通过飞行更快出行的能力</li></ul><p>所有这些选择都决定了你能获得的机会，以及你是否会享受这场游戏。你可能不喜欢扮演辅助角色，但你或许会喜欢扮演坦克、带领团队。</p><p>在现实生活中，我们可以在任何时刻选择重新开始自己的游戏。</p><p>我们可以改变自己是谁、追求什么，并积累能让我们实现那个现实的资源——比如技能、人脉网络和所处的环境。</p><p>在电子游戏中，有NPC，即非玩家角色（Non-Player Characters）。</p><p>这些是被设定为仅仅存在于游戏中的人物。他们没有丝毫的自主意识。你可以和他们互动，但在整个游戏过程中，他们始终保持不变。他们从不升级。</p><blockquote><p>我们不断地向父母、老师和朋友学习,而他们又是向他们的父母、老师和朋友学习的,这些人又受到自己人生道路、文化和社会的影响。学校、政府和宗教机构在权威等级中排名最高,往往是你在寻求解决问题的答案时最先接触到的信息来源。要在学校、社会和宗教中表现良好,你必须用学校、社会和宗教的教条来洗涤自己的思想。一种仅靠自身运转才能自洽的社会结构。毫无根基,却又必不可少。它是一种工具,而非主宰。</p></blockquote><p>通过社会规训,大多数人仍是NPC(非玩家角色),在玩着他们被设定好去玩的游戏。</p><p>从宏观角度看,这场“元游戏”就是社会。</p><p>从微观角度看,一切都是一场心智游戏。</p><p>每一种情境都存在一系列目标、问题和通往目标之间的路径,而每个人会根据自己的身份认同或视角去感知这些。</p><p>如果你能塑造自己的思维,把一种情境看作它本质上就是——一场游戏,通过设定自己的目标、构建通往目标的路径,并辨别出你可以采取的最有利行动,那么即便是平淡无奇的情境也能变得令人愉悦。</p><p>游戏之所以令人愉悦,是因为它们能让心智聚焦,并消除那些会不断复制、让你陷入无聊或焦虑状态的干扰。</p><p>游戏呈现出一系列递降的目标,每个目标都带有一定程度的挑战。</p><blockquote><p>如果你的技能与游戏所呈现的挑战不匹配,你就要倒霉了。如果你技能高而挑战低,你会感到无聊。如果你技能低而挑战高,你会感到焦虑。而当挑战刚好略高于你的技能水平,但你对自己完成它的能力充满绝对信心时,你就触及到了人类体验中——可以说是最令人愉悦的那个点(当然,这是在不借助毒品、草药或其他外源化合物的情况下就能获得的)。</p></blockquote><p>要在生活中创造愉悦感,你必须创建宏观游戏和微观游戏。</p><p>你人生的宏观游戏,是以你的愿景作为目标,以人生事业作为路径,以微观游戏作为沿途升级的方式。</p><p>微观游戏就是日常情境。你必须以开放的心态面对每一种情境,设定自己的目标,并尝试赢得那些有助于实现你愿景的游戏。其他一切都是干扰。不要玩那些游戏。如果你玩了,也要迅速从中学到东西。</p><h2 id="七-—-透镜" tabindex="-1">七 — 透镜 <a class="header-anchor" href="#七-—-透镜" aria-label="Permalink to &quot;七 — 透镜&quot;">​</a></h2><blockquote><p>你是主观现实中的一个视角载体。你有能力将这种视角超越狭隘的身份认同,从更高、更全面的角度去看待情境,将情境的背景、前景和细节都囊括其中。</p></blockquote><p>视角就像一台单反相机。</p><p>相机本身因其内部程序设定而有其局限性。</p><p>你可以为相机装上不同的镜头,以某种方式捕捉一个情境,而这种方式会根据你拍摄时的意图,影响图像被感知的方式。</p><p>在现实世界中,你的“镜头”就是各种意识形态或视角,比如宗教信仰、饮食准则、商业模式和人际关系模式。大多数人一生都只有一个镜头固定在相机上。他们永远看不到全局,也永远触及不到真相。你的任务是像一个变形者。研究多种视角,收集那些能让你从多个角度看世界的镜头。这才是你停止过度反应、并采取真正有利于自己未来的行动的方法。</p><p>相机的视野范围,就是你的觉知范围。</p><p>当你放大聚焦于某一件事时,背景就会变得模糊。这在你的实际生活中创造出专注,并消除干扰。</p><p>但一直停留在这种狭窄的聚焦中会限制你的创造力。有时,你必须拉远镜头,去收集真理、模式和创意资源。然后,你可以再拉近镜头,将它们应用到你的实际生活中。</p><blockquote><p>此时此刻的你,是你过去在心理、身体、财务和精神层面所做选择的显现。你想成为的那个人,则是你此刻、以及接下来每一个当下所做选择的显现,直到一切走向终结。</p></blockquote><p>要做出更好的决定,你不能像一个没有思想的机器人那样浑浑噩噩地过日子。</p><p>你必须停顿下来,获得视角,从一个不带反应的位置去感知情境,并做出能让理想未来成为现实的最佳选择。</p><p>如果美好的生活是由一系列高质量的决定所创造的,而高质量的决定只能来自在低质量决定之后的改进,那么频繁地、大胆地失败,同时脸上带着微笑,才是最符合你利益的做法。</p><p>在相同的时间内,一个不管自己感受如何都会做出100个决定的人,所取得的进步会呈指数级地超过那个只做1个决定、因为受制于自己思想而沦为奴隶的人。</p><p>意识的默认状态是混乱。</p><p>除非你的心智投入到某个思考、任务或刺激当中,否则它就会朝着负面方向游荡。焦虑或无聊。当我们把随机性放任进自己的生活时,负面性的潜在可能就会增加。</p><p>如果你没有明确的目的、路径或优先事项与你理想的未来保持一致、为你的注意力提供支撑,那么每产生一个积极的想法,就会伴随100个消极的想法。</p><p>我可以幻想赚很多钱,但如果我没有清晰的方向,我的思绪就会游荡到那些令人焦虑的账单、工作、学生贷款上,而这些想法又会分裂出更多的想法,直到你被压得喘不过气来。</p><p>走出去的道路,就是精通之路。</p><p>那种通过自我教育、技能习得和日常practice——不,是日常练习——为自己创造最好生活的彻底投入。</p><blockquote><p>那种对待生活的封闭式、急功近利的态度,是我们这个时代最大的陷阱,而且它的根源比一般人所认为的要深得多。讽刺的是,他们认为自己没有被封闭思维所困的原因,恰恰正是封闭思维本身。</p></blockquote><p>大多数人在遇到第一丝困难时就关闭了自己的心智。</p><p>大师们拥抱困难,因为他们已经体验过困难所呈现的那种模式:感知阈值,或称“跑步者的高潮”(runner&#39;s high)。</p><p>当你坚持挺过一种情境不断增加的难度时,最终你会突破到一种愉悦的状态。这种情况既发生在宏观层面,也发生在微观层面。</p><p>你不需要走捷径来学会走路、说话,或冲泡你最爱的咖啡。这些技能来自必要性和兴趣,尽管它们其实和学习任何其他技能一样困难。</p><p>因为你没有把自己理想的未来当作一种必要性或兴趣来看待,所以各种情境才会变得比它们本该的更困难。别和它较劲,顺着它去。</p><h2 id="八-—-公式" tabindex="-1">八 — 公式 <a class="header-anchor" href="#八-—-公式" aria-label="Permalink to &quot;八 — 公式&quot;">​</a></h2><p>大多数人在毕业后就停止了学习。</p><p>这是危险的。你会被困在重复性的任务里。生活一成不变。你会感到无聊。解药就是通过学习、构建和探索,让自己走进一种有趣的生活。</p><p>在已知的范围内,是不可能发生改变的。</p><p>同样的日常。同样的工作。同样的物理、心理和数字环境。同样的身份认同。同样的视角。</p><p>如果你感到迷失,解决方案是反直觉的。</p><p>把自己抛入未知之中,变得更加迷失。搬到新的地方去。读新的书。习得新的技能,以转换职业或建立自己的事业。</p><p>强迫自己进入一个能获得清晰认知和兴趣的地方。然后,探索出一条走出去的路。</p><p>如果你对任何事情都没有兴趣,那是因为你没有身处未知之中。你根本没有机会去发现自己的兴趣所在。</p><p>要想做好这件事,你需要:</p><ul><li><strong>一个反愿景和一个愿景</strong>,用来构建你的视角框架。</li><li><strong>一个目的</strong>,用来提供一个感知情境和识别问题的镜头。</li><li><strong>一条路径</strong>,用来为你的教育、技能习得和构建带来清晰的方向。</li><li><strong>一个优先事项</strong>,用来每一天都专注其上,支撑你的注意力。</li></ul><p>所有这些共同构建出一种能够抵御干扰、并随着你所达到的每个层次而不断扩展的心智。</p><h3 id="反愿景与愿景" tabindex="-1">反愿景与愿景 <a class="header-anchor" href="#反愿景与愿景" aria-label="Permalink to &quot;反愿景与愿景&quot;">​</a></h3><blockquote><p>首先,要对两件事有近乎残酷的清醒认知:(1)你不想要的是什么。(2)如果你继续做你一直在做的事,你最终会落到何处。观察大众,看看毫无思考的行动会通向何方。那画面并不美好。</p></blockquote><p>相比知道自己想要什么,知道自己不想要什么——通过反思与经验——要容易得多。你可以通过理解自己不想要什么,来洞察自己真正想要什么。</p><p>这是一个不断迭代的过程。</p><p>你现在认为自己想要的东西,可能在一年、一个月甚至一周之后就会改变。但如果不去犯错,你永远不会意识到这一点。错误就是你通向更好生活的指南针。</p><p>要构建你的反愿景与愿景,可以从这些问题开始:</p><ul><li>在你看来,一个毫无意义的日子是什么样的?</li><li>你理想中的一天是什么样的?</li><li>你会避开哪种类型的人作为伴侣?</li><li>你理想中的伴侣是什么样的?</li><li>你不想以怎样的方式去看、去感受、去行动?</li><li>你想以怎样的方式去看、去感受、去行动?</li><li>多少钱才算太少,不足以维持你的生活方式?为什么这算太少?</li><li>有了那笔钱,你还有什么事是做不到的?</li><li>你会厌恶生活在怎样的环境里?为什么?</li><li>你理想中的环境是什么样的?</li></ul><p>对这些问题要具体化。</p><p>把这些写在日记本或笔记本里,并随着灵感的出现不断补充。</p><h3 id="目的、路径、优先事项" tabindex="-1">目的、路径、优先事项 <a class="header-anchor" href="#目的、路径、优先事项" aria-label="Permalink to &quot;目的、路径、优先事项&quot;">​</a></h3><p>你的<strong>目的</strong>,就是你此刻生活中最迫切需要解决的问题。</p><p>那个你一直拖延着不去解决的问题。</p><blockquote><p>你人生的目的,是你想要在这个世界上解决的重大问题,但大多数人在个人、职业或社会层面的发展程度都还不足以去追寻它。目的会从表层逐渐演化到形而上的层面,而你无法跳过这些阶段。</p></blockquote><p>在你出发去解决这个世界上的重大问题之前,你必须先解决自己生活中的重大问题。</p><p>健康、财富和关系,是你迫在眉睫的问题所在之处。解决它们。仅此一点,就能为好奇心、创造力和意识腾出空间,因为你的心智不再被生存的压力所困扰。</p><p>你的<strong>路径</strong>,是一套随着你不断演化的目的而随时间演变的目标层级。</p><p>有一些技能、教育和知识,是你必须获取的,才能达到心智的新层次。这是一条永无止境的路径。精通之路。</p><p>把你生活的每个领域——健康、财富和关系——拆解成一条路径,以此发现你必须采取的那些微小的、优先级的行动,从而创造更好的生活。你不必同时专注于所有领域,但最终你都需要逐一改善它们。财富和关系只能随着你的健康程度而改善,反之亦然。</p><p>你的优先事项,将涉及每天投入一段专门的时间去学习或构建。这一点会在《项目》章节中更深入地讨论。</p><p>在你的旅程中,让好奇心引导你去发现生活所呈现的那些机遇冰山。好奇心是你沿路前行的燃料。当你不断深入未知之地时,新颖的信息会吸引你的注意力。这些信息可能是你最好的朋友,也可能是最坏的敌人。</p><p>有4条路径,可以让你进一步追随自己的好奇心。</p><ol><li><strong>欣赏</strong> —— 欣赏你所遇到的想法、人物和机会。你不必去评判或投射。就单纯地欣赏它们本来的样子。</li><li><strong>理解</strong> —— 你可以寻求更深入地理解这些机会。这需要你沉浸在与该领域相关的书籍、内容和信息之中。</li><li><strong>精通</strong> —— 一旦你理解了某件事,你就可以选择去精通它。当你感受到想要深入下去的拉力时,不要压制它。</li><li><strong>变现</strong> —— 当你在少数几个领域全力投入之后,你可以将这些技能和兴趣与商业原则相结合,靠此谋生。</li></ol><p>追随你那与愿景一致的目标层级,深入未知领域。通过自我教育获得清晰认知,执行最小优先级的任务,并保持开放的心态,去发掘你生命中新的潜能。</p><h2 id="九-——-转变" tabindex="-1">九 —— 转变 <a class="header-anchor" href="#九-——-转变" aria-label="Permalink to &quot;九 —— 转变&quot;">​</a></h2><blockquote><p>我们正生活在看似第二个黄金时代之中。正规教育体系正受到独立教育者、记者、专家和艺术家的挑战,他们试图摆脱薄薪和有限触及范围的束缚。银行体系正受到去中心化货币程序员的挑战。政府正受到远程工作和人们渴望多国公民身份以少缴税款的挑战。</p></blockquote><p>当我还是个孩子的时候,我感到孤独。我感觉自己无法与同龄人产生共鸣。他们都听从父母、老师,顺从朋友,却从不质疑这样做是否正确。他们上学,找工作,从那以后你再也没听过他们说过什么有趣的事。</p><p>正规教育有其存在的意义,但人们正逐渐失去对它能保障自己未来的信任。人们花上4到12年、投入数万美元,在此之前还经历了12年公立学校教育,最终却只换来一张纸,这样的情况太常见了。</p><p>对于那些想要充实工作和自由日程的人来说,一份工作是给不了你的。我意识到这一点是在:</p><ul><li>在大学度过了5年</li><li>还剩2年才能完成学位</li><li>即便拿到了“全额”奖学金,依然背了2万美元的贷款</li><li>明知自己想开创自己的道路 —— 找一份工作是我生命中的祸根</li><li>出于好奇心上了一门入门课程后,发现了我对网页开发的热爱</li><li>在不到一个月的时间里,通过自学掌握了整门课程的全部内容</li><li>利用自学的成果,在第一次面试后就获得了一份高薪的科技工作(此前经历了多次创业失败,不得不接受为了生存必须找份工作的现实)</li></ul><p>正规教育的现实,给了我狠狠一击。</p><p>如果我能在6个月的自学中,学到比5年正规教育更多的实用技能,那我为什么没有早点这样做呢?</p><p>如果我能通过自己的学习,获得一份比大多数人都更好、薪水更高的工作,而这最终又会转化为一项极其赚钱的生意,那我为什么要在大学里浪费那么多时间呢?</p><p>这就引出了<em>深度知识</em>的重要性。</p><blockquote><p>好奇心是通往你想做之事的道路。好奇心是让你成为你自己的东西,而在自动化工作的未来到来之际,这正是一种必需品。如果你学的东西和其他人一样,被训练去争夺那仅存的少数几个职位,那你几乎可以被任何人取代。解决之道就是深度知识。</p></blockquote><p>我喜欢把深度知识想象成心智中的一个“压缩文件包”。</p><p>随着正规教育体系像所有事物一样逐渐走向终结,我确信未来的教育将转移到线上,由创作者充当老师,每个学生都可以加入最符合自己兴趣、价值观和学习方式偏好的“学校”。不会再有一种学校体系主宰他们的童年和成年早期。</p><p>学生们会根据每位创作者在课程、导师辅导和内容中所提供的深度知识,在这些去中心化的“学校”之间,从一位创作者流转到另一位创作者。</p><blockquote><p>深度知识是那种能逐步提升学生心智层次的信息。它帮助他们解决一系列问题,朝着一个有意义的目标层级前进。</p></blockquote><p>工作的未来正在我们眼前被创造出来。</p><p>你有能力通过获取和传播深度知识,创造属于自己的事业。因为未来要求我们用心智赚钱,而不是用时间。</p><p>你必须解决自己的问题,从表层的到形而上的,以此提升你能提供给世界的价值。</p><p>互联网就是一个大社区。你的祖先曾是各自社区中的企业家。每个人都扮演着最适合自己的角色。</p><p>创业是现代的生存方式,互联网是你的狩猎场。你通过追随自己的好奇心来猎取深度知识。多巴胺是你的指南针,而要让这一切说得通,你需要摆脱那种被快速快感一点一滴喂养出来的多巴胺麻醉状态。</p><h2 id="十-——-新富人" tabindex="-1">十 —— 新富人 <a class="header-anchor" href="#十-——-新富人" aria-label="Permalink to &quot;十 —— 新富人&quot;">​</a></h2><blockquote><p>没有人说过自己想每周工作四十多个小时,用无脑的娱乐麻醉自己的心智,推迟自己的梦想,只为在某一天醒来时,疑惑时间都去了哪里。然而,这正是每个人正在做的事。</p></blockquote><p>“工作”这个词会引发一连串令人焦虑的想法和情绪,让人想到明天要做什么,后天要做什么,如此往复,直到生命尽头。</p><p>人们没有意识到,工作是生活中不可或缺的一部分。它为休息带来了对比。每个人都想把生命中的大部分时间花在沙滩上啜饮椰汁,但当他们真正拥有空闲时间时,可以说是最痛苦的时候。他们没有意识到,工作能为心智带来秩序。“毕生事业”这个概念,从未闯入这些盲目大众的脑海。</p><p>你的毕生事业,是你对未来愿景中天然的一部分。它是你把自己长期积累的价值影响力传播给他人的方式,而借助互联网的力量,这从未像现在这样触手可及。</p><p>你必须通过刻意的生活方式设计,为你的毕生事业腾出空间。如果你不主动去争取时间,它就会被别人夺走。</p><p>在一个鼓励每周工作80小时、高压环境比比皆是、几乎不留给休息和恢复的世界里,你必须反抗。</p><blockquote><p>四小时工作日、专一的专注力和有意义的工作,正在互联网的一些小圈子里成为常态,而这是有道理的。古罗马人和古希腊人、史蒂夫·乔布斯(Steve Jobs)、查尔斯·达尔文(Charles Darwin),以及一份不断增长的富有远见的思想家、战略家和创新者的名单,都将他们的成功归功于出人意料的低工作时长,同时伴以充足的休息活动,比如长时间散步。</p></blockquote><p>大多数人看到成功的创意人士,就以为他们比普通员工工作时间更长。这是错的。世界上大多数最具影响力的创意人士,他们的工作时长会让你目瞪口呆,因为他们明白专注力是有限的,而创造力需要摆脱对工作的狭窄专注。<em>休息能打开你的专注力,让你的心智能够捕捉到新的想法和解决方案。</em></p><p>要开始你的生活方式设计,请遵循以下步骤:</p><ul><li>拿出一本笔记本</li><li>写下一天中每一分钟你到底在做什么,<em>以及你为什么这样做</em></li><li>写下你在早晨、下午和夜晚的确切感受</li><li>以一种能让你感觉更好、拥有更多时间的方式,对你的一天进行优先排序、删减和重新安排 —— 这需要你对自己保持坦诚</li><li>建立一个为期一周的系统,来逆转你日常routine中的熵增</li><li>规划好你的晨间routine、专注工作routine、其他任务和会议,以及夜间routine</li><li>在接下来的一周里,回顾你的笔记本,开始对系统中不奏效的部分进行迭代优化</li></ul><p>为了确保最大化的心智产出、创造力和生活享受,有三件事需要考虑:你如何填充你的心智,你如何清空你的心智,以及你如何运用你的心智。</p><p>如何通过时间和实践建立一个日常系统,取决于你自己,但你应该在一天的各项活动中融入这三个方面。</p><ul><li><strong>填充你的心智</strong> —— 你需要教育、想法,以及能应用于目标的新颖资源。这会带来内在动机。</li><li><strong>清空你的心智</strong> —— 你不想被困在一个混乱的思绪和有用想法的泡泡里。那正是让你毫无进展的方式。把想法写下来。</li><li><strong>运用你的心智</strong> —— 你需要一个载体来聚焦你的努力。凭借你的想法和执行的清晰认知,去建造你的未来。</li></ul><p>我们已经理解了用创造性火力填充心智、以及清空心智为创造性涌现留出空间的重要性。现在我们需要学习如何将这种创造力聚焦到我们的工作中。</p><blockquote><p>4小时专注的工作,胜过8小时分心的工作。</p></blockquote><p>我小时候,听说过蒂姆·费里斯(Tim Ferris)写的《每周工作4小时》(The 4-Hour Work Week)。出于某种原因,“四小时工作日”这个概念在我整个青年时期都牢牢地印在我脑海中。</p><p>仅此一点,就改变了我人生的方向。</p><ul><li>我把每天超过4小时的工作,视为一个问题</li><li>我没有把自己想要实现的生活方式贴上“不可能”的标签</li><li>这迫使我的大脑,每当我工作超过4小时时,就去想办法寻找创造性的解决方案</li><li>我能够注意到商业中的机会,让我每天只工作2小时,而其他人却每天工作8到12小时,做着同样的事</li></ul><p>对大多数人来说,四小时工作日目前还不是一个可能的选项。不是因为你一开始必须工作更久,而是因为你必须工作得更短。</p><p>如果你有一份工作、配偶或家庭要照顾,那么显然你需要从小处着手,优先安排你的工作。从1小时的工作日开始,随着你取得成果,再逐渐增加到4小时的工作日。</p><p>为什么是4小时?因为根据个人经验、科学研究以及来自世界上最受尊敬的创意人士的轶事,3到5小时是心智能量消耗的一个甜蜜点。</p><p>以4小时为截止时限,构建了一个你可以去赢的游戏框架。如果你扮演一个只工作4小时的角色,并且已经将这一特质内化,那么你就会感受到在这段时间内完成工作的压力。</p><p>更好的是,当你把这段工作时间切分成更小的时间块时,你就创造了一个强有力的环境,能把你的专注力收窄到一种富有生产力的良性压力状态中。</p><blockquote><p>如果你能花8小时去建造别人的梦想,你就能花1小时去建造你自己的。</p></blockquote><h2 id="十一-——-技能叠加" tabindex="-1">十一 —— 技能叠加 <a class="header-anchor" href="#十一-——-技能叠加" aria-label="Permalink to &quot;十一 —— 技能叠加&quot;">​</a></h2><blockquote><p>工作的状态正在改变。专才正在被淘汰,但通才也一样。我们正生活在一个“专精化通才”的时代。你必须追随你的好奇心,痴迷于现实中的某一个缝隙,在那个领域内堆叠技能以解决迫切的问题,并让你技能树的根基向其他相关领域延伸生根。</p></blockquote><p>在这场数字文艺复兴中,成为一名专才,是让自己被取代的绝佳方式。把自己局限在一项技能里,并不是通往独立成功的道路。</p><p>如果你成为一个专才，你可以为别人打工赚一份不错的薪水，但你没意识到，他们才是你能拿到薄水的原因。你无法创造独立的收入，因为你还没学会那些能让你自己获得报酬的技能。</p><p>大公司有市场部、销售部、运营部等各种部门，它们各自承担获取客户和交付产品的角色。</p><blockquote><p>除了那些令人愉悦的分心事物之外，作为一个人，你能学习和运用的东西没有上限。个人可以学习设计、营销、写作和视频制作，从而运营一家数百万美元的企业，销售自己在生活中已经解决过的问题的解决方案。</p></blockquote><p>由于深度知识对愿意在网上寻找的人来说是可以获取的，你可以在6到12个月的专注努力下，成为任何一项技能中前10%的人。当你把下面我们要讨论的技能组合起来时，你的机会面就会呈复合式增长。</p><h3 id="信息与媒介" tabindex="-1">信息与媒介 <a class="header-anchor" href="#信息与媒介" aria-label="Permalink to &quot;信息与媒介&quot;">​</a></h3><p>没有价值交换，就不可能实现你版本的成功。你必须成为一个承载有价值信息的容器，并在关系、商业和日常生活中，用它交换你想要的那种价值形式。</p><p>换句话说，如果你想赚钱（你想要的价值形式），那你就必须用自己的价值形式，去交换那个拥有钱的人。钱不会凭空出现。</p><p>一个有价值的<strong>信息</strong>，是一种能与他人产生共鸣、能被理解、能被采取行动的沟通方式。这需要对人性和心理学有所理解。做到这一点最好的方法，就是学习<em>营销和销售</em>——因为它们包含了理解心理学的实用框架，并配有真实世界的实践。</p><p>价值由感知决定，而感知受个人世界观的影响。要用你的信息传播有价值的东西，它必须针对某个群体或个人的心智层次、身份认同和思维习惯（conditioning）来打造。</p><p>你可以打造某些特定的词语，来捕获、保持并在注意力上传递价值。<em>你必须让人们把注意力聚焦在你身上</em>，否则他们的注意力会被更具干扰性或更有价值的东西吸走。</p><p>你的信息必须模仿宇宙：</p><ul><li>讲故事</li><li>带领人们经历高潮和低谷</li><li>像你最喜欢的电影那样激发情绪</li><li>打开一个好奇回环来抓住注意力</li><li>激化一个问题，进而塑造他们的视角</li><li>通过个人经历与他们产生共鸣</li><li>暗示一个带有令人向往的最终结果的目标</li><li>提供一条他们可以遵循以实现该结果的路径</li></ul><p>价值就是行为改变。</p><p>你传播信息所用的<strong>媒介</strong>，是<em>写作或演讲</em>。</p><p>意识中有内容，集体意识中也有内容。你心智的前端是你意识注意力中的内容，互联网的前端是集体意识中的内容。你心智的后端是塑造你是谁的无意识程式，互联网的后端则是承载内容的、被编程好的操作系统。</p><p>把内容投放到虚拟现实中去，就是你通过商业为人类做贡献的方式。</p><p>从学习写作开始。通过营销和销售驾驭心理学，写出一条有价值的信息，让世界在互联网上发现它。</p><p>持续的写作有助于你的演讲。写作是每个人都能触及的。互联网上的一切都始于写作。邮件、帖子、广告、视频脚本、字幕、私信等等。不要以为人类心理学不适用于任何形式的写作，无论你在哪里写。</p><p><em>写作、演讲、营销和销售是基础技能，它们将决定你所学的任何其他技能所能取得的结果。</em></p><h3 id="以结果为导向的技能" tabindex="-1">以结果为导向的技能 <a class="header-anchor" href="#以结果为导向的技能" aria-label="Permalink to &quot;以结果为导向的技能&quot;">​</a></h3><blockquote><p>以结果为导向的技能，是你运用所选信息与媒介的方式。它们是分发你价值的容器。信息和媒介是常青不变的，而以结果为导向的技能则随时代变化。你必须把手指按在你所感兴趣领域进展的脉搏上，这样才不会随着时间推移而被淘汰。</p></blockquote><p>在当下这个时间点，以结果为导向的技能是数字化的。我们并不生活在一个印刷机刚刚发明、盈利技能都围绕它转的世界。我们生活在一个数字世界里。</p><p>这些以结果为导向的技能会随时间变化，但邮件营销、平面设计、摄像、摄影、剪辑、动画、人工智能和社交媒体，是能让我们用所选媒介、把信息运用到当下格局中的一些例子。</p><p>这些技能不仅对你自己的业务有用，对他人同样有用。所有品牌、创作者和学生，都有他们希望在个人和职业生活中解决的问题。当你把以结果为导向的技能，叠加在常青技能之上时，你既可以在自己的业务上实践，也可以创造一款产品或服务，用这些技能去帮助别人的业务成长。</p><p>如果你把读一个学位所需的时间，投入到打造一个由5万名志同道合的读者组成的邮件列表上，那已经是一个职业足球场容纳人数的两倍。现在，如果你打造一条有说服力的信息，写几封邮件，推广一款你为解决自己问题而创造出来的产品，我不会感到惊讶，如果你一个月赚到的钱，最低都能达到美国的平均年薪。</p><h2 id="第十二章-——-项目" tabindex="-1">第十二章 —— 项目 <a class="header-anchor" href="#第十二章-——-项目" aria-label="Permalink to &quot;第十二章 —— 项目&quot;">​</a></h2><p>我在自己生活中注意到的一个模式是，我总会挤出时间来打造属于自己的东西。像学校作业、客户工作，甚至工作中被分配给我的项目，都是必要的，但它们没能带给我我所追寻的那种满足感。我意识到，大多数人缺乏满足感的根源，在于他们从未学习或打造过一件他们自己选择去学习或打造的东西。</p><p>一个人心智的输入和输出，从出生起就被那条常规的人生道路所奴役——学这个，建那个，以至于人们厌恶那唯二能把他们从这种奴役中解放出来的东西。如果你不做出选择，社会就会替你选择。</p><p>从一开始就有一连串不断演变的个人项目可以着手，为我的每一天带来了新鲜感。我在多个领域获得的发现、洞见和进步，是我对生活热情的源泉。</p><p>一个项目是一个有形的目标层级，用来整理心智，而你自己就是那个无限的项目。你就是你一生的作品。你是一个承载着多个项目的项目，每个子项目都有其目的、路径与优先级，当它们被实现时，就能让你进化。项目是你在未知中抛下的一个锚，让你能穿过困难的学习经历的洪流，把自己拉过去，完成这个项目。</p><blockquote><p>学习的源头是挣扎，而不是死记硬背。学习是把知识转化为理解的过程，而你生命中最低谷的那些时刻，正是一课可叠加的经验呈现出来的时刻——但只有当你把它应用到现实中时才算数。</p></blockquote><p>项目帮你为你所学的东西建立框架。它们让你去追求一个目标，撞上一个障碍，并从随之而来的问题中框定你的思维。只有从那里，你才能真正学到某种能立即应用的有用东西。</p><p>要高效地学习信息：</p><ul><li>不要先开始学习</li><li>为你想实现的目标创建一个项目</li><li>创建一条路径或系统来实现那个目标</li><li>用你已经掌握的东西，在现实世界中开始搭建这个项目</li><li>把你正在搭建的东西教给别人（可以是朋友、家人或网络上的同行）</li><li>当你无法继续搭建或表达你的想法时，识别出知识缺口</li><li>研读深度知识来填补那些知识缺口</li><li>回到搭建和教学中去</li><li>永远重复这个过程</li></ul><p>这种学习过程利用新奇感、模式识别和自我实验，来最大化你所经历的信息流动。</p><blockquote><p>大多数人不断地学、学、学，结果到了真正要动手建造的时候，却要从头开始，因为他们意识到自己所学的一切，都无法直接用在他们所开始的那个项目上。他们没有一个针对该目标的特定视角，来解读自己所学的东西。</p></blockquote><p>永久解决你问题的唯一方法，是自我实验。</p><p>自我实验，是与盲目相信某个理论、导师、信仰体系、意识形态、操作指南或教条相反的东西。它是发现什么真正适合你、以及你那无限独特的需求的唯一方法。</p><p>对于任何给定的问题，都有几十种、甚至几百种可供你选择的解决方案。把自己局限在你所知道的那一两种上，可能无法解决你的问题。</p><p>你的任务是：</p><ul><li>研究大量针对你问题的解决方案</li><li>全部测试它们，不要执着于其中任何一个</li><li>记录它们之间的原理、模式与真相</li><li>记录哪些方法对你有效，即便未必对别人有效</li><li>开始用你所学到的东西，创造出属于你自己的解决方案</li></ul><p>这正是真正价值被培育出来的地方。这种价值可以用来盈利，也可以只是用来让你的生活变得更好。</p><p>如果你有关系上的问题：可以试试去参加一次静修、请一位治疗师、读一本有建议的书，或者直接和你的伴侣一起处理它。</p><p>如果你有金钱上的问题：可以试试制定预算、开始一份副业，或提升你的技能以获得一份薪水更高的工作。</p><p>如果你有健康问题，可以试试像肉食法或生酮饮食这样的流行饮食法，研读营养学原理，并沉浸在来自各种渠道的信息中，直到你理解了这整个拼图。</p><p>如果你生活中重要的问题没有立刻得到解决，不要因此气馁。</p><h2 id="第十三章-——-容器" tabindex="-1">第十三章 —— 容器 <a class="header-anchor" href="#第十三章-——-容器" aria-label="Permalink to &quot;第十三章 —— 容器&quot;">​</a></h2><blockquote><p>每个人都是企业家；只是有些人选择为自己在个人生活中解决的问题获得报酬。</p></blockquote><p>所有能盈利的产品，一开始都是一个项目，无论最初是否有出售的打算。如果你想创造一种有创造性的独立收入，把自己从社会的枷锁中解放出来，你就需要卖出一款有价值的产品。而还有什么比一个能解决所有生命都会遭遇的迫切问题的个人项目，更好的起点呢？</p><p>自我提升，是关于解决你自己生活中的问题。商业，是关于解决别人生活中的问题。别再把如何赚钱这件事复杂化了。别再试图去解决那些根本不存在的创造性问题。去获得能解决你自己生活中问题的技能——这本身就是一个价值的自动过滤器——然后把这个解决方案变成给别人用的产品。</p><p>商业中有4个永恒的市场：健康、财富、关系与幸福。所有迫切的问题和有意义的目标，都存在于这些领域中，无论是在你身上还是在别人身上。<em>解决你自己的问题，然后把这个解决方案卖出去。</em></p><blockquote><p>如何创办一家十亿美元的公司：别这么做。相反，先从一个人开始。如果你无法把自己的兴趣变成收入，那你就不具备开创一家需要十倍资源的企业所需的技能。</p></blockquote><p>作为一个个体，你有能力把受众吸引到你的作品面前，并把一款有价值的产品呈现在他们眼前。</p><p>这就是大多数人开始把现代商业搞复杂的地方。他们说你需要“细分领域”，去定位一群你可能根本不想为其服务的受众。现代商业建议是让你最终又陷入一份你讨厌的工作的必胜法门。</p><p>让我们用一句简单的话把这一切串起来：</p><p><strong>最有利可图的细分领域就是你自己。</strong></p><p>你的目标就是你的品牌。你的路径就是你的产品。你的优先事项就是你的内容。你的内容承载着吸引人们关注你品牌的宝贵信息。当你偶尔把产品展示给他们时，这就是你开始创造独立收入的方式。</p><p>还有什么比你在追求目标的道路上所学到的技能和兴趣的独特组合更“细分”的呢？</p><p>每个人都有相同的大目标：赚更多的钱、拥有更多的性、拥有更多的精力，以及终结自己的存在性焦虑。</p><p>虽然目标相同，但你走的路径却各不相同。如果我和另一个人都有赚钱的目标，我们都会去研究和尝试不同的事情。我可能会尝试电商或数字产品，而他们可能会尝试预算规划并开一家实体店。</p><p>通过追求你的目标，通过自我实验来解决你的问题，把个人项目变成产品，并传播有价值的信息来吸引和你有相似身份的人，我认为很难做到不赚到你想要的那么多钱——只要给它时间和不断迭代。</p><p>如果你就是那个细分领域，饱和就不再存在。每个人都会拥有一个独特的产品，服务于处于其思维层次的人群，并帮助提升集体意识。</p><blockquote><p>人类的命运并非注定。集体的进化力量，取决于构成它的个体的力量。正因如此，我们的进化，取决于你我通过有意识的个人成长所诞生的信息的繁衍，去创造出的那些个体。</p></blockquote><p>把自己变成一门生意，就是你在精神层面上进行繁衍的方式。这是你塑造全球范围内自我发展、并为人类做出贡献的方式。</p><p>当大多数人传播的信息从整体上导向邪恶与毁灭时，你却可以致力于解决问题——从表面的到形而上的——成为一个巨大的价值创造者。</p><p>让我们重申一下这整条路径：</p><ul><li>理解并体验宇宙的规律</li><li>体验人类经验的全部范围</li><li>让你的决定与理想自我的视角保持一致</li><li>追求一套目标层级，解决你生活中真正的问题</li><li>从更高层次的思维出发，用你的创造能力去建立为人类做出贡献的整体性项目</li></ul><p>去寻找想法，用你自己的双手去构建。把无形之物变成有形之物。把泥土变成黄金。在一个极度渴求深度的世界里，成为价值的源泉。</p><p>归根结底，通过《专注的艺术》（The Art of Focus）在这个世界上留下你自己的印记。</p><p>如果你想购买本书的实体版，<a href="http://theartoffocusbook.com/" target="_blank" rel="noreferrer">可以点击这里购买。</a></p><hr><p><a href="/en/letters/the-art-of-focus-official-book-summary-by-the-author-dan-koe">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',282))])}const q=e(h,[["render",u]]);export{m as __pageData,q as default};
